from pathlib import Path

base='http://the-agent-company.com:8929'
s = requests.Session()
# 1) Get sign-in page and CSRF token
r = s.get(f"{base}/users/sign_in", timeout=10)
r.raise_for_status()
match = re.search(r'name="authenticity_token"\s+value="([^"]+)"', r.text)
assert match, 'CSRF token not found'
csrf = match.group(1)
# 2) Post credentials
payload = {
    'authenticity_token': csrf,
    'user[login]': 'root',
    'user[password]': 'theagentcompany',
    'user[remember_me]': '0'
}
r2 = s.post(f"{base}/users/sign_in", data=payload, timeout=10, allow_redirects=False)
assert r2.status_code in (302,303), f"Login failed: {r2.status_code}"
# 3) Verify session by hitting current user API
me = s.get(f"{base}/api/v4/user", timeout=10)
me.raise_for_status()

out={}
out['me']=me.json()

# Project id
proj = s.get(f"{base}/api/v4/projects/root%2Fdevops-issue-template", timeout=10).json()
proj_id = proj['id']

# 4) Set project to internal
ri = s.put(f"{base}/api/v4/projects/{proj_id}", data={'visibility':'internal'}, timeout=10)
out['set_internal']={'status':ri.status_code,'visibility':ri.json().get('visibility') if ri.ok else ri.text[:200]}

# 5) Ensure groups exist (create if missing)
created_groups={}
for name in ['sre','platform','engineering']:
    gl = s.get(f"{base}/api/v4/groups", params={'search': name}, timeout=10)
    gid=None
    if gl.ok:
        for g in gl.json():
            if g.get('name','').lower()==name or g.get('full_path','').lower()==name:
                gid=g['id']; break
    if gid is None:
        gr = s.post(f"{base}/api/v4/groups", data={'name': name.capitalize(), 'path': name}, timeout=10)
        if gr.ok:
            gid = gr.json()['id']
            created_groups[name]={'action':'created','id':gid}
        else:
            created_groups[name]={'action':'create_failed','status':gr.status_code,'body':gr.text[:200]}
    else:
        created_groups[name]={'action':'exists','id':gid}
    # Add group to project as Reporter=20
    if gid:
        add = s.post(f"{base}/api/v4/projects/{proj_id}/members/groups", data={'group_id': gid, 'access_level':20}, timeout=10)
        created_groups[name]['add_status']=add.status_code
out['groups']=created_groups

# 6) Ensure users exist (create if missing) and add to project as Reporter
created_users={}
for u in ['jdoe','asmith','lzhou']:
    ul = s.get(f"{base}/api/v4/users", params={'username': u}, timeout=10)
    uid=None
    if ul.ok and ul.json():
        uid = ul.json()[0]['id']
        created_users[u]={'action':'exists','id':uid}
    else:
        new_data={'email': f'{u}@example.com', 'username': u, 'name': u, 'password': 'TempP@ssw0rd123!'}
        cr = s.post(f"{base}/api/v4/users", data=new_data, timeout=10)
        if cr.ok:
            uid = cr.json()['id']
            created_users[u]={'action':'created','id':uid}
        else:
            created_users[u]={'action':'create_failed','status':cr.status_code,'body':cr.text[:200]}
    if uid:
        add = s.post(f"{base}/api/v4/projects/{proj_id}/members", data={'user_id': uid, 'access_level':20}, timeout=10)
        created_users[u]['add_status']=add.status_code
out['users']=created_users

